/** The window chrome every screen shares: frame, title bar, three dots and the window title. */
function Chrome({ bar }: { bar: string }) {
  return (
    <><rect x="0.5" y="0.5" width="319" height="179" rx="10" fill="#0b1220" stroke="#24314a" /><rect x="0.5" y="0.5" width="319" height="24" rx="10" fill="#111a2b" /><rect x="0.5" y="14" width="319" height="11" fill="#111a2b" /><circle cx="13" cy="12.5" r="3.5" fill="#f87171" /><circle cx="24" cy="12.5" r="3.5" fill="#fbbf24" /><circle cx="35" cy="12.5" r="3.5" fill="#4ade80" /><text x="160" y="16" textAnchor="middle" fill="#93a1bb" fontSize="9">{bar}</text></>
  );
}

const keyOf = (title: string) => title.trim().toLowerCase();

/** The titles that have a drawing (lower case): what the coverage test checks the catalogue against. */
export const DRAWN_IDEAS: readonly string[] = Object.keys(SCREENS);

export function hasIdeaPreview(title: string): boolean {
  return Object.prototype.hasOwnProperty.call(SCREENS, keyOf(title));
}

/** What the idea's drawing shows, as its accessible name; null when there is no drawing. */
export function ideaPreviewLabel(title: string): string | null {
  const screen = hasIdeaPreview(title) ? SCREENS[keyOf(title)] : null;
  return screen ? `${title} preview: ${screen.about}` : null;
}

/** The idea's screen, or null when there is no drawing for it. */
export function IdeaPreview({ title }: { title: string }) {
  const label = ideaPreviewLabel(title);
  if (!label) return null;
  const screen = SCREENS[keyOf(title)];
  return (
    <svg className="ip-svg" role="img" aria-label={label} viewBox="0 0 320 180"
         preserveAspectRatio="xMidYMid meet">
      <Chrome bar={screen.bar} />
      {screen.body}
    </svg>
  );
}
